when.condition:
@{
        if (context.Variables.ContainsKey("requested-model")) { return false; }
        if (!context.Variables.ContainsKey("allowed-deployments")) { return false; }
        var segments = context.Request.OriginalUrl.Path.Split('/');
        var i = System.Array.IndexOf(segments, "deployments");
        if (i < 0 || i + 1 >= segments.Length) { return false; }
        return !((string)context.Variables["allowed-deployments"]).Split(',').Contains(segments[i + 1]);
    }
